#!/usr/bin/env bash
# /**
#  * @file clean.sh
#  * @brief Removes every release artifact generated by `scripts/build.sh` from `dist/` (PKG-094).
#  * @details Standalone, idempotent cleaner runnable from any working directory (PKG-095) without
#  * any prior build or release-gate execution, in fail-fast order:
#  * 1. Scope guard (PKG-096, PKG-098): an absent `dist/` is a successful no-op; a non-directory
#  *    `dist` entry aborts with a FAILED diagnostic.
#  * 2. File sweep (PKG-096): every `dist/` regular file matching the PKG-072 generated (legacy declaration and tarball outputs of earlier builds included, PKG-071)
#  *    classification (`*.js`, `*.js.map`, `*.d.ts`, `*.d.ts.map`, `*.tgz`, `*.tsbuildinfo`,
#  *    `*.tmp`) is removed; symlinks, directories, and every other entry are non-generated and
#  *    preserved, and no path outside `dist/` is ever touched.
#  * 3. Pruning (PKG-097): emptied ancestor directories of removed artifacts are pruned
#  *    deepest-first, including `dist/` itself when it ends up empty; a directory still holding
#  *    any entry is preserved.
#  * 4. Reporting (PKG-101): one stdout line per removed path plus a final result line naming
#  *    PASS; any removal failure prints a FAILED diagnostic on stderr naming the entry.
#  * No dependencies are installed and no packages are published (PKG-099); no destructive git
#  * command is invoked (PKG-100).
#  * @return Exit code 0 on success, including when `dist/` is absent; 1 on any removal failure
#  *         (PKG-098).
#  * @pre Nothing beyond `bash`, `find`, `sort`, `uniq`, `dirname`, `rmdir`, `rm`, and `ls` on PATH.
#  * @post `dist/` contains no generated build artifacts; `dist/` itself is absent when no entry
#  *       remains; non-generated entries are untouched.
#  * @note Writes only under `dist/`; the NUL-delimited file list lives in one OS-temp file removed
#  *       by the EXIT trap. Complexity O(n) in `dist/` entry count.
#  * @satisfies PKG-094, PKG-095, PKG-096, PKG-097, PKG-098, PKG-099, PKG-100, PKG-101
#  */
set -euo pipefail
cd "$(dirname "$0")/.."

readonly DIST_DIR="dist"

# NUL-delimited `dist/` file list under the OS temp root; removed by the EXIT trap.
FILE_LIST=""

# /**
#  * @brief Prints one informational line on stdout with the clean tag.
#  * @param message {string} Text printed after the tag.
#  * @return {void}
#  * @side_effect Writes to stdout.
#  */
log() {
  printf '[clean] %s\n' "$*"
}

# /**
#  * @brief Aborts the cleanup with a FAILED diagnostic naming the failed entry.
#  * @details Writes `[clean] FAILED: <message>` to stderr and exits 1 (PKG-098, PKG-101);
#  * the EXIT trap then removes the temporary file list. Complexity O(1).
#  * @param message {string} Diagnostic naming the failed step or entry.
#  * @return {void} Never returns.
#  * @side_effect Terminates the process with exit code 1.
#  */
fail() {
  printf '[clean] FAILED: %s\n' "$*" >&2
  exit 1
}

# /**
#  * @brief EXIT trap: removes the temporary file list preserving the original exit status.
#  * @details A failed temp-file removal on an otherwise successful run turns the result into
#  * exit 1 with a FAILED diagnostic (PKG-098). Complexity O(1).
#  * @return {void} Terminates with the resulting exit status.
#  * @side_effect Removes `$FILE_LIST` when set.
#  */
on_exit() {
  local exit_status=$?
  trap - EXIT
  if [ -n "$FILE_LIST" ]; then
    if ! rm -f "$FILE_LIST"; then
      printf '[clean] FAILED: could not remove temporary file %s\n' "$FILE_LIST" >&2
      if [ "$exit_status" -eq 0 ]; then
        exit_status=1
      fi
    fi
  fi
  exit "$exit_status"
}

# /**
#  * @brief Classifies one dist-relative path as a generated build artifact.
#  * @details Pattern set `*.js`, `*.js.map`, `*.d.ts`, `*.d.ts.map`, `*.tgz`, `*.tsbuildinfo`,
#  * `*.tmp`, identical to the `scripts/build.sh` classifier (PKG-072); matching is
#  * case-sensitive. Pure, O(1).
#  * @param relative {string} Path relative to `dist/`.
#  * @return {number} 0 when generated; 1 when non-generated.
#  */
is_generated_output() {
  case "$1" in
    *.js | *.js.map | *.d.ts | *.d.ts.map | *.tgz | *.tsbuildinfo | *.tmp) return 0 ;;
    *) return 1 ;;
  esac
}

# /**
#  * @brief Removes one directory when it is empty, tolerating non-empty directories.
#  * @details `rmdir` succeeds only on an empty directory; a directory still holding any entry is
#  * preserved by design because it carries non-generated content (PKG-096, PKG-097). A directory
#  * that is still empty after a failed `rmdir` reports a real removal error (PKG-098).
#  * Complexity O(1) plus one directory listing on the failure path.
#  * @param dir {string} Candidate directory path; ancestors of removed artifacts or `dist/` itself.
#  * @return {void}
#  * @throws {exit 1} Via `fail` when the directory is empty yet cannot be removed.
#  * @side_effect Removes `dir` when empty.
#  */
prune_emptied_dir() {
  local dir="$1"
  if [ ! -d "$dir" ]; then
    return 0
  fi
  if rmdir -- "$dir" 2>/dev/null; then
    log "removed emptied directory: $dir"
    return 0
  fi
  if [ -z "$(ls -A "$dir")" ]; then
    fail "could not remove emptied directory: $dir"
  fi
  return 0
}

trap on_exit EXIT

# Scope guard (PKG-096, PKG-098): absent dist/ is a successful no-op; a non-directory entry fails.
if [ ! -e "$DIST_DIR" ]; then
  log "nothing to clean: $DIST_DIR/ is absent"
  log "PASS: removed 0 generated artifact(s) from $DIST_DIR/"
  exit 0
fi
if [ ! -d "$DIST_DIR" ]; then
  fail "$DIST_DIR exists but is not a directory"
fi

# File sweep (PKG-096): NUL-delimited enumeration into a temp file so a `find` failure is never
# masked by pipeline status; only generated regular files are removed.
FILE_LIST="$(mktemp "${TMPDIR:-/tmp}/mcp-google-api-clean.XXXXXX")"
if ! find "$DIST_DIR" -type f -print0 >"$FILE_LIST"; then
  fail "could not enumerate $DIST_DIR/"
fi

removed=0
removed_dirs=()
while IFS= read -r -d '' path; do
  relative="${path#"$DIST_DIR"/}"
  if ! is_generated_output "$relative"; then
    continue
  fi
  if ! rm -f -- "$path"; then
    fail "could not remove generated artifact: $path"
  fi
  log "removed: $path"
  removed=$((removed + 1))
  parent="$(dirname -- "$path")"
  while [ "$parent" != "$DIST_DIR" ] && [ "$parent" != "." ]; do
    removed_dirs+=("$parent")
    parent="$(dirname -- "$parent")"
  done
done <"$FILE_LIST"

# Pruning (PKG-097): reverse-lexical order visits children before parents, so emptied ancestor
# chains collapse in one pass; `dist/` itself is attempted last and removed only when empty.
if [ "${#removed_dirs[@]}" -gt 0 ]; then
  while IFS= read -r -d '' dir; do
    prune_emptied_dir "$dir"
  done < <(printf '%s\0' "${removed_dirs[@]}" | sort -rz | uniq -z)
fi
prune_emptied_dir "$DIST_DIR"

log "PASS: removed $removed generated artifact(s) from $DIST_DIR/"
exit 0
